// 与路径一致的等距经纬投影。视图外的合法坐标保持视图外位置，不能钳到边缘假装在地图内。
export function projectChina(lon, lat) {
  if (!Number.isFinite(lon) || !Number.isFinite(lat) || Math.abs(lon) > 180 || Math.abs(lat) > 90) {
    const error = new RangeError('地图坐标必须是有效的经纬度数值');
    error.code = 'VISUAL_MAP_COORDINATE_INVALID';
    throw error;
  }
  const { west, east, south, north, width, height } = CHINA_MAP_VIEWBOX;
  return { x: (lon - west) * width / (east - west), y: (north - lat) * height / (north - south) };
}

